544 |     /// @inheritdoc IParticlePositionManager
545 |     function swap(
546 |         address token0,
547 |         address token1,
548 |         uint256 amountIn,
549 |         uint256 amountOutMinimum,
550 |         bytes calldata data
551 |     ) external override nonReentrant returns (uint256 amount0, uint256 amount1) {
552 |         (amount0, amount1) = SwapPosition.swap(token0, token1, amountIn, amountOutMinimum, DEX_AGGREGATOR, data);
