554 | 
555 |     /*=============================================================
556 |                               Admin logic
557 |     ==============================================================*/
558 | 
559 |     /// @inheritdoc IParticlePositionManager
560 |     function updateDexAggregator(address dexAggregator) external override onlyOwner {
561 |         if (dexAggregator == address(0)) revert Errors.InvalidValue();
562 |         DEX_AGGREGATOR = dexAggregator;
563 |         emit UpdateDexAggregator(dexAggregator);
564 |     }
565 | 
566 |     /// @inheritdoc IParticlePositionManager
567 |     function updateLiquidationRewardFactor(uint128 liquidationRewardFactor) external override onlyOwner {
568 |         if (liquidationRewardFactor > _LIQUIDATION_REWARD_FACTOR_MAX) revert Errors.InvalidValue();
569 |         LIQUIDATION_REWARD_FACTOR = liquidationRewardFactor;
570 |         emit UpdateLiquidationRewardFactor(liquidationRewardFactor);
571 |     }
572 | 
573 |     /// @inheritdoc IParticlePositionManager
574 |     function updateFeeFactor(uint256 feeFactor) external override onlyOwner {
575 |         if (feeFactor > _FEE_FACTOR_MAX) revert Errors.InvalidValue();
576 |         FEE_FACTOR = feeFactor;
577 |         emit UpdateFeeFactor(feeFactor);
578 |     }
579 | 
580 |     /// @inheritdoc IParticlePositionManager
581 |     function updateLoanTerm(uint256 loanTerm) external override onlyOwner {
582 |         if (loanTerm > _LOAN_TERM_MAX) revert Errors.InvalidValue();
583 |         LOAN_TERM = loanTerm;
584 |         emit UpdateLoanTerm(loanTerm);
585 |     }
586 | 
587 |     /// @inheritdoc IParticlePositionManager
588 |     function updateTreasuryRate(uint256 treasuryRate) external override onlyOwner {
589 |         if (treasuryRate > _TREASURY_RATE_MAX) revert Errors.InvalidValue();
590 |         _treasuryRate = treasuryRate;
591 |         emit UpdateTreasuryRate(treasuryRate);
592 |     }
593 | 
594 |     /// @inheritdoc IParticlePositionManager
595 |     function withdrawTreasury(address token, address recipient) external override onlyOwner nonReentrant {
596 |         uint256 withdrawAmount = _treasury[token];
597 |         if (withdrawAmount > 0) {
598 |             if (recipient == address(0)) {
599 |                 revert Errors.InvalidRecipient();
600 |             }
601 |             _treasury[token] = 0;
